-- ============================================================
-- ZavrsniRad - Oracle Database 21c XE seed skripta
-- Adaptirano iz documentation/ini.sql (izvorno PostgreSQL) za
-- Oracle shemu/korisnika "senecura".
--
-- Pokretanje (spojen kao senecura korisnik):
--   sqlplus senecura/<lozinka>@<host>:<port>/<service> @ini_oracle.sql
-- ili kroz Oracle SQL Developer (otvori skriptu, Run Script / F5).
--
-- Test lozinka za SVE seed korisnike: lozinka123
-- (bcrypt hash generiran preko PHP password_hash(), provjerava se
--  s password_verify() u api/auth/login.php)
--
-- Razlike prema PostgreSQL izvorniku:
--   serial          -> NUMBER GENERATED BY DEFAULT AS IDENTITY
--   boolean         -> NUMBER(1) CHECK (... IN (0,1)), true/false -> 1/0
--   varchar(n)      -> VARCHAR2(n)
--   text            -> VARCHAR2(4000)  (opis polja su kratki tekstovi)
--   now()           -> SYSTIMESTAMP
--   TIMESTAMPTZ lit.-> TIMESTAMP '... +HH:MI' (ANSI literal s pomakom)
--   multi-row VALUES-> pojedinačni INSERT po retku (Oracle 21c nema
--                      ANSI VALUES (a),(b),(c) sintaksu - stigla tek u 23c)
--   plpgsql trigger -> PL/SQL BEFORE UPDATE trigger po tablici
-- ============================================================

BEGIN
    FOR t IN (
        SELECT 'evidencije' table_name FROM dual UNION ALL
        SELECT 'akcije' FROM dual UNION ALL
        SELECT 'tip_evidencije' FROM dual UNION ALL
        SELECT 'smjene' FROM dual UNION ALL
        SELECT 'posjeti' FROM dual UNION ALL
        SELECT 'umirovljenik' FROM dual UNION ALL
        SELECT 'lokacije' FROM dual UNION ALL
        SELECT 'korisnik' FROM dual
    ) LOOP
        BEGIN
            EXECUTE IMMEDIATE 'DROP TABLE ' || t.table_name || ' CASCADE CONSTRAINTS PURGE';
        EXCEPTION
            WHEN OTHERS THEN
                IF SQLCODE != -942 THEN RAISE; END IF;
        END;
    END LOOP;
END;
/

CREATE TABLE korisnik (
    id NUMBER GENERATED BY DEFAULT AS IDENTITY,
    ime VARCHAR2(255) NOT NULL,
    prezime VARCHAR2(255) NOT NULL,
    lozinka VARCHAR2(255) NOT NULL,
    email VARCHAR2(255) NOT NULL UNIQUE,
    uloga NUMBER NOT NULL,
    aktivan NUMBER(1) DEFAULT 1 NOT NULL CHECK (aktivan IN (0, 1)),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT korisnik_pk PRIMARY KEY (id)
);

CREATE TABLE lokacije (
    id NUMBER GENERATED BY DEFAULT AS IDENTITY,
    parent_id NUMBER,
    naziv VARCHAR2(255) NOT NULL,
    tip NUMBER NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT lokacije_pk PRIMARY KEY (id)
);

CREATE TABLE umirovljenik (
    id NUMBER GENERATED BY DEFAULT AS IDENTITY,
    ime VARCHAR2(255) NOT NULL,
    prezime VARCHAR2(255) NOT NULL,
    lokacija_id NUMBER NOT NULL,
    aktivan NUMBER(1) DEFAULT 1 NOT NULL CHECK (aktivan IN (0, 1)),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT umirovljenik_pk PRIMARY KEY (id)
);

CREATE TABLE posjeti (
    id NUMBER GENERATED BY DEFAULT AS IDENTITY,
    umirovljenik_id NUMBER NOT NULL,
    ime VARCHAR2(255) NOT NULL,
    prezime VARCHAR2(255) NOT NULL,
    datum DATE NOT NULL,
    upisao_id NUMBER NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT posjeti_pk PRIMARY KEY (id)
);

CREATE TABLE smjene (
    id NUMBER GENERATED BY DEFAULT AS IDENTITY,
    korisnik_id NUMBER NOT NULL,
    datum DATE NOT NULL,
    smjena NUMBER NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT smjene_pk PRIMARY KEY (id)
);

CREATE TABLE tip_evidencije (
    id NUMBER NOT NULL,
    naziv VARCHAR2(255) NOT NULL,
    opis VARCHAR2(500) NOT NULL,
    aktivan NUMBER(1) DEFAULT 1 NOT NULL CHECK (aktivan IN (0, 1)),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT tip_evidencije_pk PRIMARY KEY (id)
);

CREATE TABLE akcije (
    id NUMBER NOT NULL,
    tip_id NUMBER NOT NULL,
    naziv VARCHAR2(255) NOT NULL,
    opis VARCHAR2(500) NOT NULL,
    aktivna NUMBER(1) DEFAULT 1 NOT NULL CHECK (aktivna IN (0, 1)),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT akcije_pk PRIMARY KEY (id, tip_id)
);

CREATE TABLE evidencije (
    id NUMBER GENERATED BY DEFAULT AS IDENTITY,
    umirovljenik_id NUMBER,
    lokacija_id NUMBER,
    izvrsio_id NUMBER NOT NULL,
    akcija_tip_id NUMBER NOT NULL,
    akcija_id NUMBER NOT NULL,
    datum_vrijeme TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    vrijednost_num NUMBER(10, 2),
    vrijednost_string VARCHAR2(255),
    vrijednost_bool NUMBER(1) CHECK (vrijednost_bool IN (0, 1)),
    opis VARCHAR2(4000),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT evidencije_pk PRIMARY KEY (id),
    CONSTRAINT evidencije_target_chk CHECK (
        umirovljenik_id IS NOT NULL OR lokacija_id IS NOT NULL
    ),
    CONSTRAINT evidencije_value_chk CHECK (
        vrijednost_num IS NOT NULL
        OR vrijednost_string IS NOT NULL
        OR vrijednost_bool IS NOT NULL
        OR opis IS NOT NULL
    )
);

ALTER TABLE lokacije ADD CONSTRAINT lokacija_parent_fk FOREIGN KEY (parent_id) REFERENCES lokacije (id);
ALTER TABLE umirovljenik ADD CONSTRAINT umirovljenik_fk3 FOREIGN KEY (lokacija_id) REFERENCES lokacije (id);
ALTER TABLE posjeti ADD CONSTRAINT posjeti_umirovljenik_fk FOREIGN KEY (umirovljenik_id) REFERENCES umirovljenik (id);
ALTER TABLE posjeti ADD CONSTRAINT posjeti_upisao_fk FOREIGN KEY (upisao_id) REFERENCES korisnik (id);
ALTER TABLE smjene ADD CONSTRAINT smjene_korisnik_fk FOREIGN KEY (korisnik_id) REFERENCES korisnik (id);
ALTER TABLE akcije ADD CONSTRAINT akcije_tip_fk FOREIGN KEY (tip_id) REFERENCES tip_evidencije (id);
ALTER TABLE evidencije ADD CONSTRAINT evidencije_umirovljenik_fk FOREIGN KEY (umirovljenik_id) REFERENCES umirovljenik (id);
ALTER TABLE evidencije ADD CONSTRAINT evidencije_lokacija_fk FOREIGN KEY (lokacija_id) REFERENCES lokacije (id);
ALTER TABLE evidencije ADD CONSTRAINT evidencije_akcija_fk FOREIGN KEY (akcija_id, akcija_tip_id) REFERENCES akcije (id, tip_id);
ALTER TABLE evidencije ADD CONSTRAINT evidencije_izvrsio_fk FOREIGN KEY (izvrsio_id) REFERENCES korisnik (id);

CREATE OR REPLACE TRIGGER umirovljenik_updated
BEFORE UPDATE ON umirovljenik
FOR EACH ROW
BEGIN
    :NEW.updated_at := SYSTIMESTAMP;
END;
/

CREATE OR REPLACE TRIGGER posjeti_updated
BEFORE UPDATE ON posjeti
FOR EACH ROW
BEGIN
    :NEW.updated_at := SYSTIMESTAMP;
END;
/

CREATE OR REPLACE TRIGGER korisnik_updated
BEFORE UPDATE ON korisnik
FOR EACH ROW
BEGIN
    :NEW.updated_at := SYSTIMESTAMP;
END;
/

CREATE OR REPLACE TRIGGER smjene_updated
BEFORE UPDATE ON smjene
FOR EACH ROW
BEGIN
    :NEW.updated_at := SYSTIMESTAMP;
END;
/

CREATE OR REPLACE TRIGGER evidencije_updated
BEFORE UPDATE ON evidencije
FOR EACH ROW
BEGIN
    :NEW.updated_at := SYSTIMESTAMP;
END;
/

CREATE OR REPLACE TRIGGER akcije_updated
BEFORE UPDATE ON akcije
FOR EACH ROW
BEGIN
    :NEW.updated_at := SYSTIMESTAMP;
END;
/

