DECLARE
    v_max NUMBER;
BEGIN
    SELECT NVL(MAX(id), 0) + 1 INTO v_max FROM korisnik;
    EXECUTE IMMEDIATE 'ALTER TABLE korisnik MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH ' || v_max || ')';

    SELECT NVL(MAX(id), 0) + 1 INTO v_max FROM lokacije;
    EXECUTE IMMEDIATE 'ALTER TABLE lokacije MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH ' || v_max || ')';

    SELECT NVL(MAX(id), 0) + 1 INTO v_max FROM umirovljenik;
    EXECUTE IMMEDIATE 'ALTER TABLE umirovljenik MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH ' || v_max || ')';

    SELECT NVL(MAX(id), 0) + 1 INTO v_max FROM posjeti;
    EXECUTE IMMEDIATE 'ALTER TABLE posjeti MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH ' || v_max || ')';

    SELECT NVL(MAX(id), 0) + 1 INTO v_max FROM smjene;
    EXECUTE IMMEDIATE 'ALTER TABLE smjene MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH ' || v_max || ')';

    SELECT NVL(MAX(id), 0) + 1 INTO v_max FROM evidencije;
    EXECUTE IMMEDIATE 'ALTER TABLE evidencije MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH ' || v_max || ')';
END;
/

COMMIT;

